architecture.h4_f:
msg = CBOR{v:1, লিখনী, উত্তৰ, পঠোৱা_এ}
ct = AES-GCM-256-এনক্ৰিপ্ট(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {চাইফাৰটেক্সট: হেক্স(ct), nonce: হেক্স}

cryptoWire.h1_f:
pt = CBOR{v:1, লিখনী, উত্তৰ_লৈ?, থ্ৰেড_আইডি?, উল্লেখ?, পঠোৱা_এ}
ct = AES-GCM-256-এনক্ৰিপ্ট(ৰুম_কী, nonce, pt, aad=hex(ৰুম_আইডি))
তাঁৰ = CBOR{
  v: ১,
  ciphertext: hex(ct), // চলক দৈৰ্ঘ্য
  nonce: হেক্স(১২ বি),
  প্ৰেৰক_ছ্যুডো: hex(16 B),
  sent_at: ইউনিক্স_এমএছ
}

cryptoWire.h5_f:
বাহিৰৰ = CBOR{
  উৎস_ন'ড: hex32,
  লক্ষ্য_ব্যৱহাৰকাৰী: int64,
  inner_ciphertext: বাইট,
  inner_nonce: বাইট,
  sent_at: ইউনিক্স_এমএছ
}
sig = Ed25519-Sign(উৎস_priv, বাহিৰৰ)
POST /federation/deliver { খাম: বাহিৰৰ, sig: hex64 }

auth.h1_f:
POST /api/প্ৰমাণীকৰণ/পঞ্জীয়ন
  { ব্যৱহাৰকাৰীৰ নাম, পাছৱৰ্ড, x25519_public_key, প্ৰদৰ্শন_নাম, ফোন?, ইমেইল?, avatar_emoji }

উত্তৰ ২০১ সৃষ্টি কৰা হৈছে:
  { অভিগম_টোকেন, সতেজ_টোকেন, ব্যৱহাৰকাৰী_আইডি, ব্যৱহাৰকাৰীৰ নাম, ... }

auth.h3_f:
access_token পেলোড:
  { উপ: ব্যৱহাৰকাৰী_আইডি, jti: ডিভাইচ_আইডি, ধৰণ: "প্ৰৱেশ", exp: এতিয়া + 15min }
refresh_token পেলোড:
  { উপ: ব্যৱহাৰকাৰী_আইডি, jti: ডিভাইচ_আইডি, টাইপ: "সতেজ", exp: এতিয়া + 30d }

HS256-.env ৰ পৰা ন'ডৰ 64-বাইট গোপনীয়তাৰ সৈতে স্বাক্ষৰিত

auth.h4_f:
register_begin(): প্ৰত্যাহ্বান = ৰেণ্ড(32)
                    বিকল্পসমূহ = { rp.id, ব্যৱহাৰকাৰী.id, pubKeyCredParams, প্ৰত্যাহ্বান }
                    বিকল্পসমূহ ঘূৰাই দিয়ক

register_finish(প্ৰমাণীকৰণ):
  TPM / সুৰক্ষিত Enclave মূল CA ৰ বিৰুদ্ধে প্ৰমাণীকৰণ পৰীক্ষা কৰক
  store { প্ৰমাণপত্ৰ_আইডি, ৰাজহুৱা_কি, কাউণ্টাৰ: 0 }

auth.h7_f:
POST /api/প্ৰমাণীকৰণ/qr/আৰম্ভ
  → { nonce: ১২৮-বিট হেক্স, ttl: ৬০ }
QR পেলোড = { nonce, ব্যৱহাৰকাৰী_আইডি, চাৰ্ভাৰ: "https://node.example" }

POST /api/প্ৰমাণীকৰণ/qr/পৰীক্ষা কৰক { nonce }
  → নতুন ডিভাইচ পঞ্জীয়ন কৰা হৈছে; জে ডব্লিউ টি সকল উভতি আহিল।

rooms.h6_f:
প্ৰেৰক_ছ্যুডো = HMAC-SHA256(কোঠা_ছ্যুডো_লৱণ, প্ৰেৰক_আইডি)[:16] // 32 হেক্স
ciphertext = AES-GCM-এনক্ৰিপ্ট(ৰুম_কী, nonce, CBOR_payload, aad = ৰুম_আইডি)

ফেন-আউট ফ্ৰেম: { ধৰণ:"m", কোঠা, বাৰ্তা:{id, ct, nonce, প্ৰেৰক_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumible/init {ফাইলৰ নাম, আকাৰ, টুকুৰা_আকাৰ_ইংগিত}
            ← {আপলোড_আইডি, টুকুৰা_আকাৰ}
chunk PUT /api/files/resumible/{আপলোড_id}/chunk/{অফছেট} <ct বাইট>
            ← ২০৪
চূড়ান্ত কৰক POST /api/files/resutable/{upload_id}/finalise {plain_blake3}
            ← ২০১ {ফাইল_আইডি, url}
TTL অসম্পূৰ্ণ: ২৪ ঘন্টা

files.h4_f:
অস্বীকাৰ_তালিকা = {
  "এপ্লিকেচন/x-dosexec",
  "এপ্লিকেচন/x-sharedlib",
